:root {
  --bg: #f4f5f7;
  --panel: #ffffff;
  --border: #e2e5ea;
  --text: #1f2430;
  --muted: #6b7280;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --danger: #dc2626;
  --warning-bg: #fef3c7;
  --warning-text: #92400e;
  --radius: 10px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app-header {
  padding: 1.5rem clamp(1rem, 4vw, 3rem) 0.5rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.8rem;
}

.tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.layout {
  display: grid;
  grid-template-columns: minmax(260px, 340px) 1fr;
  gap: 1.5rem;
  align-items: start;
  padding: 1rem clamp(1rem, 4vw, 3rem) 3rem;
}

@media (max-width: 760px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
}

.panel h2 {
  margin-top: 0;
  font-size: 1.1rem;
}

.bookmark-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.bookmark-form label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: #374151;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

.bookmark-form input,
.bookmark-form textarea,
.list-controls input,
.list-controls select {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}

.bookmark-form textarea {
  resize: vertical;
}

button {
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border: none;
  border-radius: 8px;
  padding: 0.55rem 0.9rem;
  background: var(--accent);
  color: #fff;
}

button:hover {
  background: var(--accent-hover);
}

button.secondary {
  background: #e5e7eb;
  color: #111827;
}

button.link-danger {
  background: none;
  color: var(--danger);
  padding: 0.25rem 0.4rem;
}

button.link-danger:hover {
  background: #fee2e2;
}

button.link-plain {
  background: none;
  color: var(--accent);
  padding: 0.25rem 0.4rem;
}

button.link-plain:hover {
  background: #eff6ff;
}

.form-error {
  margin: 0;
  color: var(--danger);
  font-size: 0.85rem;
}

.form-warning {
  margin: 0;
  background: var(--warning-bg);
  color: var(--warning-text);
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  font-size: 0.85rem;
}

.list-controls {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.list-controls input[type="search"] {
  flex: 1 1 220px;
}

.bookmark-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.bookmark-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.9rem 1rem;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.bookmark-main {
  min-width: 0;
}

.bookmark-title {
  font-weight: 600;
  font-size: 1rem;
  color: var(--accent);
  text-decoration: none;
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark-title:hover {
  text-decoration: underline;
}

.bookmark-url {
  color: var(--muted);
  font-size: 0.82rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.bookmark-notes {
  margin: 0.35rem 0 0;
  font-size: 0.85rem;
  color: #4b5563;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.tag-row {
  margin-top: 0.5rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.tag {
  background: #eef2ff;
  color: #3730a3;
  border-radius: 999px;
  padding: 0.1rem 0.55rem;
  font-size: 0.72rem;
}

.bookmark-actions {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  align-items: flex-end;
  white-space: nowrap;
}

.state {
  text-align: center;
  color: var(--text);
  padding: 2rem 1rem;
}

.state .muted {
  color: var(--muted);
  margin-top: 0.25rem;
}

.muted {
  color: var(--muted);
}

dialog {
  border: none;
  border-radius: var(--radius);
  padding: 1.5rem;
  width: min(420px, 92vw);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

dialog::backdrop {
  background: rgba(15, 23, 42, 0.45);
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  margin: 0.5rem 0 0;
  padding: 0;
}

